css:
#dyn-mosaic-theme[data-theme="tmpl-polaroid-wall"]  {
  overflow: hidden;
  background:
    radial-gradient(ellipse 70% 55% at 50% 42%, rgba(18, 48, 62, 0.4), transparent 62%),
    #000;
}
#dyn-mosaic-theme[data-theme="tmpl-polaroid-wall"] .dyn-polaroid-stage  {
  position: absolute;
  transform-origin: top left;
}
#dyn-mosaic-theme[data-theme="tmpl-polaroid-wall"] .dyn-polaroid-pos  {
  position: absolute;
  will-change: transform;
}
#dyn-mosaic-theme[data-theme="tmpl-polaroid-wall"] .dyn-polaroid-inner  {
  position: relative;
  display: inline-block;
  opacity: 0;
  will-change: transform, opacity;
}
#dyn-mosaic-theme[data-theme="tmpl-polaroid-wall"] .dyn-polaroid  {
  background: #fff;
  border-radius: 3px;
  padding: 12px 12px 14px 12px;
  overflow: visible;
  box-shadow:
    0 6px 20px rgba(0, 0, 0, 0.5),
    0 2px 6px rgba(0, 0, 0, 0.35),
    inset 0 0 0 1px rgba(0, 0, 0, 0.06);
}
#dyn-mosaic-theme[data-theme="tmpl-polaroid-wall"] .dyn-polaroid img  {
  display: block;
  width: 100%;
  height: auto;
  aspect-ratio: 3 / 4;
  object-fit: cover;
  object-position: center center;
  border-radius: 1px;
  background: #222;
}
#dyn-mosaic-theme[data-theme="tmpl-polaroid-wall"] .dyn-polaroid-band  {
  display: block;
  margin-top: 10px;
}
#dyn-mosaic-theme[data-theme="tmpl-polaroid-wall"] .anim-enter-drop  {
  animation: dyn-drop-in 0.55s cubic-bezier(0.22, 1.2, 0.36, 1) both;
}
#dyn-mosaic-theme[data-theme="tmpl-polaroid-wall"] .anim-enter-toss  {
  animation: dyn-toss-in 0.5s cubic-bezier(0.25, 1.3, 0.5, 1) both;
}
#dyn-mosaic-theme[data-theme="tmpl-polaroid-wall"] .anim-enter-place  {
  animation: dyn-place-in 0.45s cubic-bezier(0.34, 1.56, 0.64, 1) both;
}
#dyn-mosaic-theme[data-theme="tmpl-polaroid-wall"] .anim-exit  {
  animation: dyn-lift-out 0.6s ease-in both;
}
@keyframes dyn-drop-in  {
  0%  {
   transform: translateY(-70px) scale(1.08) rotate(var(--drop-rot, 3deg));
   opacity: 0;
   }
  60%  {
   opacity: 1;
   }
  100%  {
   transform: translateY(0) scale(1) rotate(0deg);
   opacity: 1;
   }
}
@keyframes dyn-toss-in  {
  0%  {
   transform: translateX(var(--toss-x, -50px)) translateY(-40px) scale(1.1) rotate(var(--toss-rot, -10deg));
   opacity: 0;
   }
  50%  {
   opacity: 1;
   }
  100%  {
   transform: translateX(0) translateY(0) scale(1) rotate(0deg);
   opacity: 1;
   }
}
@keyframes dyn-place-in  {
  0%  {
   transform: scale(0.7);
   opacity: 0;
   }
  100%  {
   transform: scale(1);
   opacity: 1;
   }
}
@keyframes dyn-lift-out  {
  0%  {
   transform: translateY(0) scale(1);
   opacity: 1;
   }
  100%  {
   transform: translateY(-25px) scale(0.94);
   opacity: 0;
   }
}

