#dyn-mosaic-theme[data-theme="tmpl-polaroid-wall"] .dyn-card  {
  background: #fff;
  border-radius: 3px;
  padding: 10px 10px 28px;
  box-shadow: 0 6px 20px rgba(0,0,0,.5), 0 2px 6px rgba(0,0,0,.35);
  overflow: visible;
}
#dyn-mosaic-theme[data-theme="tmpl-polaroid-wall"] .dyn-card img  {
  display: block;
   width: 100%;
   height: 100%;
   object-fit: cover;
   border-radius: 1px;
   background: #222;
}
#dyn-mosaic-theme[data-theme="tmpl-polaroid-wall"] .dyn-card::after  {
  content: "";
  position: absolute;
   left: 10px;
   right: 10px;
   bottom: 8px;
   height: 14px;
  background: linear-gradient(#f4f1ea, #e7e1d6);
}
#dyn-mosaic-theme[data-theme="tmpl-polaroid-wall"] .dyn-card:nth-child(3n+1)  {
   animation: dyn-drop-in .55s cubic-bezier(.22,1.2,.36,1) both;
   }
#dyn-mosaic-theme[data-theme="tmpl-polaroid-wall"] .dyn-card:nth-child(3n+2)  {
   animation: dyn-toss-in .5s cubic-bezier(.25,1.3,.5,1) both;
   }
#dyn-mosaic-theme[data-theme="tmpl-polaroid-wall"] .dyn-card:nth-child(3n)  {
   animation: dyn-place-in .45s cubic-bezier(.34,1.56,.64,1) both;
   }
